import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { ScrollArea } from "@/components/ui/scroll-area";
import { ShoppingCart, Package, Tag } from "lucide-react";

const products = [
    { id: "PRD-001", name: "Premium Wireless Headphones", price: 299.99, category: "Electronics", stock: 15 },
    { id: "PRD-002", name: "Ergonomic Office Chair", price: 199.50, category: "Furniture", stock: 8 },
    { id: "PRD-003", name: "Mechanical Keyboard", price: 129.00, category: "Peripherals", stock: 24 },
];

export default function ShopPage() {
    return (
        <div className="flex flex-col gap-4">
            <h1 className="text-2xl font-bold">Shop</h1>
            <ScrollArea className="h-[calc(100vh-12rem)]">
                <div className="space-y-4">
                    {products.map((product) => (
                        <Card key={product.id}>
                            <CardHeader>
                                <CardTitle>{product.name}</CardTitle>
                                <div className="flex items-center gap-2">
                                    <Badge variant="outline">{product.category}</Badge>
                                    <Badge variant="outline">{product.stock} in stock</Badge>
                                </div>
                            </CardHeader>
                            <CardContent>
                                <div className="flex items-center justify-between">
                                    <div className="flex items-center gap-2">
                                        <ShoppingCart className="h-4 w-4" />
                                        <span>{product.price}</span>
                                    </div>
                                    <Button>Add to Cart</Button>
                                </div>
                            </CardContent>
                        </Card>
                    ))}
                </div>
            </ScrollArea>
        </div>
    );
}
